pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Alice calls addToBalance() with 1 ether
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Bob calls addToBalance() with 1 ether
        address bob = address(0x5678);
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.addToBalance{value: 1 ether}();

        // Alice withdraws her balance
        vm.prank(alice);
        c.withdrawBalance();

        // After withdrawal, Alice's balance should be 0
        assertEq(c.getBalance(alice), 0);
    }
}

